def squared(logit, y):  return (logit - y) ** 2
def zero_one(logit, y): return int(logit * y <= 0)
for logit in (-1.0, 0.5, 1.0, 4.0, 8.0):
    print(f"y=+1 logit={logit:4}: squared={squared(logit, 1):5.2f}, "
          f"zero_one={zero_one(logit, 1)}")

class Vocabulary:
    """문자열 <-> 정수 사전. 처음 보는 단어는 새 번호를 받는다."""
    def __init__(self):
        self.index_to_string = []
        self.string_to_index = {}
    def get_index(self, s):
        if s not in self.string_to_index:
            self.string_to_index[s] = len(self.index_to_string)
            self.index_to_string.append(s)
        return self.string_to_index[s]
vocab = Vocabulary()
indices = [vocab.get_index(t) for t in "the cat in the hat".split()]
print(indices, vocab.index_to_string)
